input.script:
export const meta = {
  name: 'explore-agent-native-x402',
  description: 'Adversarial research + critique of repositioning CipherBox as x402-metered private storage for AI agents',
  phases: [
    { title: 'Research', detail: 'x402 protocol reality, agent-storage landscape, agent money/data economy' },
    { title: 'Critique', detail: 'ZK-key technical fit (codebase), unit economics, strategic positioning' },
  ],
}

const RESEARCH_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    lens: { type: 'string' },
    keyFindings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          claim: { type: 'string' },
          detail: { type: 'string' },
          confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
          sources: { type: 'array', items: { type: 'string' } },
        },
        required: ['claim', 'detail', 'confidence'],
      },
    },
    implicationsForIdea: { type: 'string' },
  },
  required: ['lens', 'keyFindings', 'implicationsForIdea'],
}

const CRITIQUE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {
    lens: { type: 'string' },
    steelman: { type: 'string' },
    objections: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          title: { type: 'string' },
          why: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          mitigation: { type: 'string' },
        },
        required: ['title', 'why', 'severity'],
      },
    },
    openQuestions: { type: 'array', items: { type: 'string' } },
    verdict: { type: 'string' },
  },
  required: ['lens', 'steelman', 'objections', 'verdict'],
}

phase('Research')
const researchLenses = [
  {
    key: 'x402-protocol',
    prompt: `Research the x402 payment protocol for a strategic decision. Use WebSearch/WebFetch (and exa/tavily/firecrawl/ref if available) for CURRENT (late-2025/early-2026) facts; do not rely only on training data — mark confidence per finding.
Investigate: (1) What x402 IS — the HTTP 402 "Payment Required" revival, Coinbase's x402 spec, the request → 402 challenge → signed payment payload → facilitator settlement flow; (2) Settlement — which chains/stablecoins (USDC on Base?), facilitators, on-chain vs off-chain, latency, per-tx cost, minimum viable amounts; (3) Maturity & adoption as of early 2026 — who shipped it, SDKs/libraries, the x402 "Bazaar"/discovery directory, related agent-commerce standards (Coinbase AgentKit/CDP, Google AP2, Skyfire); (4) METERING fit — is x402 one-shot per-request only, or can it meter streaming/usage/subscriptions? refunds/disputes/chargebacks? (5) Limitations & criticisms.
Set lens='x402-protocol'. keyFindings each with sources (URLs). In implicationsForIdea, assess how well a per-request x402 rail fits metering access to a STATEFUL storage service whose real cost is per-GB-month + bandwidth + pinning, not per-request.`,
  },
  {
    key: 'agent-storage-landscape',
    prompt: `Research the landscape and REAL demand for "storage for AI agents", especially private/encrypted/decentralized. Use WebSearch/WebFetch for current facts; mark confidence.
Cover: (1) Who offers storage aimed at agents or via web3 — web3.storage/Storacha, Lighthouse, Walrus (Mysten), Akave, Arweave/Filecoin, plus S3 and MCP filesystem/storage servers; which expose pay-per-use or x402; (2) What do AI agents actually need to store (RAG corpora, agent memory/state, task artifacts, end-user files acted on via delegated capability) and how sensitive is it — is zero-knowledge / client-side encryption a real REQUIREMENT or a nice-to-have for agent workloads? (3) Demand signals — products/protocols pitching "pay-per-use private storage for agents", any traction/funding/usage; (4) MCP ecosystem — are there storage MCP servers, and would "CipherBox as an MCP server" fit how agents consume tools?
Set lens='agent-storage-landscape'. keyFindings with sources. implicationsForIdea = is there a real wedge for ZK private storage for agents, and who is the likely FIRST customer?`,
  },
  {
    key: 'agent-money-and-data-economy',
    prompt: `Research how autonomous agents hold/spend money and any existing "pay-per-use data/storage/API via x402" products. Use WebSearch/WebFetch; mark confidence.
Cover: (1) Agent wallets & spend controls — how agents get a wallet, custody, budget caps, who funds it (the agent's human/org principal vs an autonomous treasury); Coinbase AgentKit/CDP server wallets, ERC-4337/session keys; (2) Existing x402-metered APIs/data services + the x402 ecosystem directory — concrete examples of what is sold per-request today; (3) Agent-commerce protocols beyond x402 (Google AP2, Skyfire, Nevermined, Payman) and how they relate; (4) The ACCOUNTLESS tension — x402 targets keyless/accountless per-request access; how do services needing PER-USER STATE (a persistent private vault) reconcile statelessness with persistent identity/keys?
Set lens='agent-money-and-data-economy'. keyFindings with sources. implicationsForIdea = can a per-request x402 rail coexist with a persistent, per-user, key-bound private vault, and what identity/key model does that imply?`,
  },
]
const research = (await parallel(
  researchLenses.map((l) => () =>
    agent(l.prompt, { label: `research:${l.key}`, phase: 'Research', schema: RESEARCH_SCHEMA, effort: 'high' }),
  ),
)).filter(Boolean)

const digest = research
  .map(
    (r) =>
      `### ${r.lens}\n` +
      (r.keyFindings || [])
        .map((f) => `- [${f.confidence}] ${f.claim} — ${f.detail}`)
        .join('\n') +
      `\nIMPLICATIONS: ${r.implicationsForIdea}`,
  )
  .join('\n\n')
log(`Research complete: ${research.length} lenses. Feeding digest into critique.`)

phase('Critique')
const critiqueLenses = [
  {
    key: 'zk-key-technical-fit',
    prompt: `You are ADVERSARIALLY assessing whether CipherBox's zero-knowledge model can serve AUTONOMOUS AI AGENTS paying via x402. Read the ACTUAL architecture in this repo (cwd is the CipherBox root): docs/AUTHENTICATION_ARCHITECTURE.md, docs/ARCHITECTURE.md, docs/FILESYSTEM_SPECIFICATION.md, and skim packages/sdk-core/src and packages/crypto/src to confirm how keys are derived/held (Web3Auth-derived private key in client memory; ECIES key wrapping; per-folder/per-file keys; IPNS record signing; TEE republishing; MFA/device approval).
THE CRUX: ZK requires client-held keys the server never sees; x402 targets accountless, per-request, keyless access.
Assess: (a) Where would an agent's vault encryption keys live? Enumerate viable models — (i) agent has its own Web3Auth identity + wallet; (ii) a human/org principal delegates a SCOPED capability/sub-key to the agent (relate to the existing sharing/ECIES re-wrap and the 'blind-share-social-graph' seed); (iii) ephemeral per-task vaults the agent creates and hands a key to its principal; (iv) server-held keys (which BREAKS ZK — call it out). (b) What concretely breaks or must be built: key custody for a non-human, IPNS signing by an agent, ECIES re-wrap for delegated access, MFA/device-approval (human-designed), session/JWT auth vs x402's accountless model, SDK ergonomics for agents (and a possible MCP server). (c) Does the EXISTING programmable SDK + mountable vault genuinely reduce the build, or is the agent-key model net-new?
Set lens='zk-key-technical-fit'. Give a steelman (why the existing substrate genuinely fits), objections (severity blocker/major/minor + mitigation), openQuestions, and a verdict on technical coherence of ZK + agent + x402.`,
  },
  {
    key: 'unit-economics',
    prompt: `ADVERSARIALLY assess the unit-economics coherence of metering CipherBox storage to agents via x402 micropayments.
Consider: (1) Storage cost is per-GB-month + bandwidth + pinning + IPNS republish (ongoing/stateful), NOT per-request — does per-request x402 metering map onto that, or is a hybrid (deposit/streaming/subscription/escrow) needed? (2) Settlement economics — if x402 settles on-chain (USDC/Base), per-tx cost vs the micro-amounts charged; does $0.0001/request make sense if settlement/gas is higher; batching/payment-channels? (3) What exactly is metered — upload bytes, download bytes, pin-duration, request count, IPNS publishes? (4) Refunds/disputes/abuse — paying to store illegal/huge data, quota, griefing, prepaid vs postpaid; (5) Does this REPLACE or COMPLEMENT the M4 human subscription billing (Stripe)? The user already says human billing is still needed.
Set lens='unit-economics'. steelman, objections (severity + mitigation), openQuestions, verdict on whether the money model holds.`,
  },
  {
    key: 'strategic-positioning',
    prompt: `ADVERSARIALLY assess the strategic repositioning: "CipherBox should stop trying to beat Google/OneDrive/Proton Drive and instead become x402-metered private storage INFRASTRUCTURE for AI agents." Use WebSearch for any market/traction signals; mark confidence.
Consider: (1) Is the premise sound — is consumer ZK storage a losing fight given limited resources, and is agent-infra a better wedge? (2) TAM & timing — is AI-agent-commerce / agent-storage real and fundable NOW (early 2026) or speculative; risk of being too early; (3) Differentiation — why CipherBox vs "S3 + an x402 wrapper", vs web3 storage (Storacha/Walrus/Lighthouse) adding x402; is ZK the moat or a niche; (4) Wedge & first customer — who buys first, the minimal lovable version, GTM; (5) Risk of falling between two stools — abandoning consumers without winning agents; do existing v1.0 users get stranded; (6) Does the existing substrate (programmable SDK, mountable vaults, sharing, decentralized persistence) give a credible right-to-win.
Set lens='strategic-positioning'. steelman, objections (severity + mitigation), openQuestions, verdict on strategic soundness.`,
  },
]
const critique = (await parallel(
  critiqueLenses.map((l) => () =>
    agent(l.prompt + `\n\n## Research digest to ground your critique:\n` + digest, {
      label: `critique:${l.key}`,
      phase: 'Critique',
      schema: CRITIQUE_SCHEMA,
      effort: 'high',
    }),
  ),
)).filter(Boolean)

return { research, critique }

